options(stringsAsFactors=FALSE,survey.lonely.psu='adjust'); Sys.setenv(OPENBLAS_NUM_THREADS='1',VECLIB_MAXIMUM_THREADS='1')
root<-'./TB_metabolome_exposome_20261115_2130';out<-file.path(root,'临床升级_双组学_20261116');.libPaths(c(file.path(root,'analysis_MWAS_ExWAS/Rlib'),.libPaths()));suppressPackageStartupMessages({library(survey);library(data.table)})
set.seed(20261116); logmsg<-function(...)cat(format(Sys.time(),'%F %T'),..., '\n')
fa<-c('LBXCAP','LBXLAR','LBXMR1','LBXPEN','LBXPM1','LBXMRG','LBXST1','LBXAR1','LBXDA1','LBXTSA','LBXLG1','LBXML1','LBXPL1','LBXVC1','LBXOL1','LBXEN1','LBXNR1','LBXLNA','LBXALN','LBXGLA','LBXSD1','LBXED1','LBXHGL','LBXET1','LBXARA','LBXEPA','LBXDTA','LBXDP3','LBXDP6','LBXDHA');met<-c('LBXBPB','LBXBCD','LBXTHG')
mods<-list(SFA=c('LBXCAP','LBXLAR','LBXMR1','LBXPEN','LBXPM1','LBXMRG','LBXST1','LBXAR1','LBXDA1','LBXTSA','LBXLG1'),MUFA=c('LBXML1','LBXPL1','LBXVC1','LBXOL1','LBXEN1','LBXNR1'),n3=c('LBXALN','LBXSD1','LBXEPA','LBXDP3','LBXDHA'),n6=c('LBXLNA','LBXGLA','LBXED1','LBXHGL','LBXARA','LBXDTA','LBXDP6'))
a<-as.data.frame(readRDS(file.path(root,'analysis_MWAS_ExWAS/derived/analysis_2011-2012.rds'))); w<-as.data.frame(readRDS(file.path(root,'output/2011-2012/NHANES_2011-2012_full_population_wide_TBflags.rds')));stopifnot(!anyDuplicated(a$SEQN),!anyDuplicated(w$SEQN));w<-w[match(a$SEQN,w$SEQN),];stopifnot(all(a$SEQN==w$SEQN));for(v in c('LBXTBA','LBXTBN','LBXTBM','LBXTBIN','DRD360','DRD340','DIQ010','LBXGH','TBQ040','TBDRUIND','WTDRD1','DR1T_PF_SEAFD_HI','DR1T_PF_SEAFD_LOW'))if(v%in%names(w))a[[v]]<-as.numeric(w[[v]])
for(v in c(met,fa)){s<-sub('^LBX','LBD',v); cmt<-paste0(s,'LC'); if(v=='LBXBPB')cmt<-'LBDBPBLC';if(v=='LBXBCD')cmt<-'LBDBCDLC';if(v=='LBXTHG')cmt<-'LBDTHGLC';if(cmt%in%names(w))a[[paste0(v,'_lc')]]<-as.numeric(w[[cmt]]);a[[paste0('x_',v)]]<-ifelse(is.finite(a[[v]])&a[[v]]>0,log2(a[[v]]),NA_real_)}
for(k in names(mods)){mat<-a[,mods[[k]],drop=FALSE];a[[paste0('fa_',k)]]<-ifelse(complete.cases(mat)&rowSums(mat,na.rm=TRUE)>0,log2(rowSums(mat,na.rm=TRUE)),NA_real_)}
a$fish30<-factor(ifelse(a$DRD360==1,'Yes',ifelse(a$DRD360==2,'No',NA)),levels=c('No','Yes'));a$dm_self<-factor(ifelse(a$DIQ010==1,'Yes',ifelse(a$DIQ010==2,'No',NA)),levels=c('No','Yes'));a$qft_diff<-a$LBXTBA-a$LBXTBN;a$tst10<-ifelse(!is.na(a$TBDRUIND),as.integer(a$TBDRUIND>=10),NA);a$tst15<-ifelse(!is.na(a$TBDRUIND),as.integer(a$TBDRUIND>=15),NA);a$tst_gt10<-ifelse(!is.na(a$TBDRUIND),as.integer(a$TBDRUIND>10),NA)
a<-a[is.finite(a$WTFAS2YR)&a$WTFAS2YR>0&!is.na(a$SDMVPSU)&!is.na(a$SDMVSTRA),,drop=FALSE];a$adult<-!is.na(a$age)&a$age>=20;a$qvalid<-!is.na(a$QFT)&a$QFT%in%c(0,1);a$birth<-factor(a$foreign_born,levels=c(0,1),labels=c('US','NonUS'));a$smoking<-factor(a$smoking);base<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=~WTFAS2YR,nest=TRUE,data=a)
cv2<-c('age','sex_male','race','educ','PIR');cv3<-c(cv2,'birth');cv4<-c(cv3,'smoking');cv5<-c(cv4,'fish30');dom<-a$adult&a$qvalid
flow<-data.frame(stage=c('FA weight >0, design known','Adult >=20','Adult valid QFT','Adult QFT and baseline covariates','Adult QFT plus nativity smoking fish','Adult QFT plus baseline all 3 metals and 30 FA'),n=c(nrow(a),sum(a$adult),sum(dom),sum(dom&complete.cases(a[,cv2])),sum(dom&complete.cases(a[,cv5])),sum(dom&complete.cases(a[,c(cv2,paste0('x_',c(met,fa)))]))),events=c(sum(a$QFT==1,na.rm=TRUE),sum(a$adult&a$QFT==1,na.rm=TRUE),sum(dom&a$QFT==1),sum(dom&complete.cases(a[,cv2])&a$QFT==1),sum(dom&complete.cases(a[,cv5])&a$QFT==1),sum(dom&complete.cases(a[,c(cv2,paste0('x_',c(met,fa)))])&a$QFT==1)));write.csv(flow,file.path(out,'output/01_flow.csv'),row.names=FALSE)
qc<-do.call(rbind,lapply(c(met,fa),function(v){lc<-paste0(v,'_lc');z<-a$adult & is.finite(a[[v]]);q<-if(lc%in%names(a))a[[lc]] else rep(NA_real_,nrow(a));data.frame(variable=v,comment_variable=if(lc%in%names(a))sub('^LBX','LBD',paste0(v,'LC')) else NA,n_adult=sum(a$adult),n_measured=sum(z),n_comment=sum(z&!is.na(q)),n_below=sum(z&q==1,na.rm=TRUE),pct_below=if(sum(z&!is.na(q)))100*sum(z&q==1,na.rm=TRUE)/sum(z&!is.na(q)) else NA)}));qc$comment_variable[match(met,qc$variable)]<-c('LBDBPBLC','LBDBCDLC','LBDTHGLC');write.csv(qc,file.path(out,'output/02_LOD_audit.csv'),row.names=FALSE,na='')
safefit<-function(y,terms,mask,family='binomial',term=terms[1]){z<-data.frame(n=sum(mask,na.rm=TRUE),events=if(family=='binomial')sum(mask & a[[y]]==1,na.rm=TRUE) else sum(mask & a$QFT==1,na.rm=TRUE),df=NA,beta=NA,se=NA,low=NA,high=NA,p=NA,status='error',warning='');if(z$n<30|| (y=='QFT'&&z$events<10)){z$warning<-'insufficient observations';return(z)};msg<-character();tryCatch(withCallingHandlers({sub<-subset(base,mask);df<-degf(sub);f<-as.formula(paste(y,'~',paste(terms,collapse='+')));fit<-svyglm(f,sub,family=if(family=='binomial')quasibinomial() else gaussian());b<-unname(coef(fit)[term]);se<-unname(sqrt(diag(vcov(fit)))[term]);if(!is.finite(b)||!is.finite(se)||se<=0||df<=0)stop('coefficient or standard error not estimable');z$df<-df;z$beta<-b;z$se<-se;z$low<-b-qt(.975,df)*se;z$high<-b+qt(.975,df)*se;z$p<-2*pt(-abs(b/se),df);z$status<-if(isTRUE(fit$converged))'ok' else 'not_converged'},warning=function(w){msg<<-c(msg,conditionMessage(w));invokeRestart('muffleWarning')}),error=function(e){msg<<-c(msg,conditionMessage(e))});z$warning<-paste(unique(msg),collapse=' | ');z}
grid<-expand.grid(metal=met,fa=fa,stringsAsFactors=FALSE)
logmsg('same sample stepwise 90 x 5');rs<-list();rf<-list();for(i in seq_len(nrow(grid))){x<-paste0('x_',grid$metal[i]);m<-paste0('x_',grid$fa[i]);mask<-dom&complete.cases(a[,c(x,m,cv5)]);for(j in 1:5){cv<-list(c('age','sex_male'),cv2,cv3,cv4,cv5)[[j]];fit<-safefit('QFT',c(x,m,cv),mask,term=x);rs[[length(rs)+1]]<-cbind(grid[i,],step=paste0('M',j),fit,OR=exp(fit$beta),OR_low=exp(fit$low),OR_high=exp(fit$high));ff<-safefit('QFT',c(x,m,cv),mask,term=m);rf[[length(rf)+1]]<-cbind(grid[i,],step=paste0('M',j),ff,OR=exp(ff$beta),OR_low=exp(ff$low),OR_high=exp(ff$high))}};s<-do.call(rbind,rs);s$q_BH<-ave(s$p,s$step,FUN=function(v)p.adjust(v,'BH',n=nrow(grid)));write.csv(s,file.path(out,'output/03_same_sample_models.csv'),row.names=FALSE,na='');sf<-do.call(rbind,rf);sf$q_BH<-ave(sf$p,sf$step,FUN=function(v)p.adjust(v,'BH',n=nrow(grid)));write.csv(sf,file.path(out,'output/03b_same_sample_fatty_acid_terms.csv'),row.names=FALSE,na='')
logmsg('QFT TST sensitivity');z<-list();for(i in seq_len(nrow(grid))){x<-paste0('x_',grid$metal[i]);m<-paste0('x_',grid$fa[i]);variants<-list(QFT_all=dom,QFT_exclude_near_cut=dom & !is.na(a$qft_diff)&(a$qft_diff<.2 | a$qft_diff>.7),QFT_exclude_prior_TB=dom & !is.na(a$TBQ040)&a$TBQ040==2,TST_ge10=a$adult & !is.na(a$tst10),TST_gt10=a$adult & !is.na(a$tst_gt10),TST_ge15=a$adult & !is.na(a$tst15));for(nm in names(variants)){y<-if(grepl('TST_ge10',nm))'tst10' else if(grepl('TST_gt10',nm))'tst_gt10' else if(grepl('TST_ge15',nm))'tst15' else 'QFT';mask<-variants[[nm]]&complete.cases(a[,c(x,m,cv4)]);fit<-safefit(y,c(x,m,cv4),mask,term=x);z[[length(z)+1]]<-cbind(grid[i,],outcome=nm,fit,OR=exp(fit$beta),OR_low=exp(fit$low),OR_high=exp(fit$high))}};z<-do.call(rbind,z);z$q_BH<-ave(z$p,z$outcome,FUN=function(v)p.adjust(v,'BH',n=90));write.csv(z,file.path(out,'output/04_phenotype_sensitivity.csv'),row.names=FALSE,na='')
logmsg('birth interaction metals and FA modules');b<-list();features<-c(paste0('x_',met),paste0('fa_',names(mods)));for(v in features){mask<-dom&complete.cases(a[,c(v,cv4)]);term<-paste0(v,':birthNonUS');f<-safefit('QFT',c(v,cv4,paste0(v,':birth')),mask,term=term);if(f$status=='error'&&grepl('not estimable',f$warning))f<-safefit('QFT',c(v,cv4,paste0('birth:',v)),mask,term=paste0('birthNonUS:',v));f$us_n<-sum(mask&a$birth=='US');f$us_events<-sum(mask&a$birth=='US'&a$QFT==1);f$nonus_n<-sum(mask&a$birth=='NonUS');f$nonus_events<-sum(mask&a$birth=='NonUS'&a$QFT==1);b[[length(b)+1]]<-cbind(feature=v,f,OR_ratio=exp(f$beta),low_OR=exp(f$low),high_OR=exp(f$high))};b<-do.call(rbind,b);b$q_BH<-p.adjust(b$p,'BH',n=length(features));write.csv(b,file.path(out,'output/05_nativity_interactions.csv'),row.names=FALSE,na='')
logmsg('QFT-specific XM interaction, fixed four pairs');pairs<-data.frame(metal=c('LBXTHG','LBXTHG','LBXBPB','LBXBCD'),fa=c('LBXEPA','LBXDHA','LBXVC1','LBXPM1'));int<-list();for(i in 1:nrow(pairs)){x<-paste0('x_',pairs$metal[i]);m<-paste0('x_',pairs$fa[i]);mask<-dom&complete.cases(a[,c(x,m,cv4)]);f<-safefit(m,c(x,'QFT',paste0(x,':QFT'),cv4),mask,'gaussian',paste0(x,':QFT'));int[[i]]<-cbind(pairs[i,],f)};int<-do.call(rbind,int);int$q_BH<-p.adjust(int$p,'BH',n=nrow(pairs));write.csv(int,file.path(out,'output/06_QFT_XM_difference.csv'),row.names=FALSE,na='')
logmsg('quantitative QFT antigen nil exploratory');q<-list();for(v in features){mask<-dom & a$QFT==1 & is.finite(a$qft_diff)&complete.cases(a[,c(v,cv4)]);a$q_response<-ifelse(is.finite(a$qft_diff),asinh(a$qft_diff),NA);base<-update(base,q_response=a$q_response);f<-safefit('q_response',c(v,cv4),mask,'gaussian',v);q[[length(q)+1]]<-cbind(feature=v,f)};q<-do.call(rbind,q);q$q_BH<-p.adjust(q$p,'BH',n=length(features));write.csv(q,file.path(out,'output/07_QFT_quantitative.csv'),row.names=FALSE,na='')
logmsg('high LOD CAP binary sensitivity');cap<-list();a$cap_detect<-ifelse(is.na(a$LBXCAP_lc),NA,1-as.integer(a$LBXCAP_lc));base<-update(base,cap_detect=a$cap_detect);for(xv in met){x<-paste0('x_',xv);mask<-dom&complete.cases(a[,c(x,'cap_detect',cv4)]);f<-safefit('QFT',c(x,'cap_detect',cv4),mask,term='cap_detect');cap[[length(cap)+1]]<-cbind(metal=xv,analysis='CAP_detected_vs_below',f,OR=exp(f$beta),OR_low=exp(f$low),OR_high=exp(f$high))};cap<-do.call(rbind,cap);cap$q_BH<-p.adjust(cap$p,'BH',n=length(met));write.csv(cap,file.path(out,'output/09_CAP_LOD_sensitivity.csv'),row.names=FALSE,na='');
logmsg('counts and sample coding');tab<-as.data.frame(table(a$QFT,a$tst10,useNA='ifany'));names(tab)<-c('QFT','TST10','n');write.csv(tab,file.path(out,'output/08_QFT_TST_counts.csv'),row.names=FALSE);writeLines(capture.output(sessionInfo()),file.path(out,'logs/sessionInfo.txt'));saveRDS(list(data=a,met=met,fa=fa,mods=mods,cv2=cv2,cv4=cv4),file.path(out,'output/analysis_data_private.rds'));logmsg('DONE')
